package com.wizzadrds.theworldremembers.equipment;
import com.mojang.serialization.Codec; import net.minecraft.server.MinecraftServer; import net.minecraft.server.level.ServerLevel; import net.minecraft.resources.Identifier; import net.minecraft.world.level.saveddata.*; import java.util.*;
public final class NpcEquipmentManager extends SavedData { private final Map<UUID,String> mainHands=new HashMap<>(); private static final Codec<NpcEquipmentManager> CODEC=Codec.unboundedMap(Codec.STRING.xmap(UUID::fromString,UUID::toString),Codec.STRING).xmap(m->{var x=new NpcEquipmentManager();x.mainHands.putAll(m);return x;},x->x.mainHands); private static final SavedDataType<NpcEquipmentManager> TYPE=new SavedDataType<>(Identifier.fromNamespaceAndPath("the_world_remembers","equipment"),NpcEquipmentManager::new,CODEC,null); public static NpcEquipmentManager get(MinecraftServer s){ServerLevel l=s.getLevel(ServerLevel.OVERWORLD);return l==null?new NpcEquipmentManager():l.getDataStorage().computeIfAbsent(TYPE);} public String mainHand(UUID id){return mainHands.get(id);} public void observeMainHand(UUID id,String item){if(item==null||item.isBlank())return;if(!mainHands.containsKey(id)){mainHands.put(id,item);setDirty();}} }
